@layer reset, base, components, utilities;

@layer base {
  :where(h1, h2, h3) { text-wrap: balance; }
  :where(button, input, select, textarea) { font: inherit; }
}
@layer components { .card { border: 1px solid var(--border); } }

*, *::before, *::after { box-sizing: border-box; }

.page { min-block-size: 100dvh; }
.sticky-toolbar { position: sticky; inset-block-start: 0; }
.dialog-backdrop { position: fixed; inset: 0; }

.shell {
  display: grid;
  grid-template-columns: minmax(14rem, 20rem) minmax(0, 1fr);
  gap: 1.5rem;
}
.actions { display: flex; flex-wrap: wrap; gap: .75rem; }
.content { min-inline-size: 0; }

.card-list { container-type: inline-size; }
.card { display: grid; gap: 1rem; }
@container (min-width: 36rem) {
  .card { grid-template-columns: 12rem 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; }
}

:focus-visible {
  outline: 3px solid CanvasText;
  outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
  .animated { animation: none; transition: none; }
}
@media (forced-colors: active) {
  .control { border: 1px solid ButtonText; }
}
